window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["coinbase"]={html:"<div class=\"own-coinbase\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────────── -->\n  <header class=\"cb-nav\" id=\"cbNav\">\n    <a class=\"cb-wordmark\" href=\"#cb-top\" aria-label=\"Northwind home\">Northwind</a>\n    <nav class=\"cb-menu\" aria-label=\"Primary\">\n      <a href=\"#cb-explore\">Operations</a>\n      <a href=\"#cb-platform\">Platform</a>\n      <a href=\"#cb-institutions\">Institutions</a>\n      <a href=\"#cb-developers\">Developers</a>\n      <a href=\"#cb-company\">Company</a>\n    </nav>\n    <div class=\"cb-nav-right\">\n      <button class=\"cb-ico\" type=\"button\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button>\n      <a class=\"cb-nav-link\" href=\"#\">Sign in</a>\n      <a class=\"cb-btn cb-btn-primary cb-btn-sm\" href=\"#cb-pricing\">Get started</a>\n      <button class=\"cb-burger\" type=\"button\" id=\"cbBurger\" aria-label=\"Open menu\" aria-expanded=\"false\"><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"cb-top\">\n    <!-- ── DARK HERO with layered product-ui cards ────────────────────────── -->\n    <section class=\"cb-hero\" aria-labelledby=\"cbHeroH\">\n      <div class=\"cb-hero-copy\">\n        <span class=\"cb-badge\">Institutional</span>\n        <h1 id=\"cbHeroH\" class=\"cb-hero-title\">Operations data,<br>handled with care</h1>\n        <p class=\"cb-hero-sub\">One governed ledger for throughput, yield, and cost — with the reconciliation and audit trail your operations desk already expects.</p>\n        <div class=\"cb-hero-cta\">\n          <a class=\"cb-btn cb-btn-primary cb-btn-lg\" href=\"#cb-pricing\">Get started</a>\n          <a class=\"cb-btn cb-btn-outline\" href=\"#cb-platform\">See how it works</a>\n        </div>\n      </div>\n      <div class=\"cb-hero-stack\" aria-hidden=\"true\">\n        <article class=\"cb-ui-card cb-ui-main\">\n          <div class=\"cb-ui-top\"><span class=\"cb-ui-title\">Operations ledger</span><span class=\"cb-ui-live\">Live</span></div>\n          <div class=\"cb-ui-balance\">\n            <span class=\"cb-ui-label\">Units reconciled</span>\n            <span class=\"cb-ui-amount\">316,258</span>\n          </div>\n          <svg class=\"cb-ui-chart\" viewBox=\"0 0 320 84\" preserveAspectRatio=\"none\">\n            <path d=\"M0 66 40 58 80 62 120 44 160 50 200 30 240 36 280 20 320 26\" fill=\"none\" stroke=\"#0052ff\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n            <path d=\"M0 66 40 58 80 62 120 44 160 50 200 30 240 36 280 20 320 26 320 84 0 84Z\" fill=\"#0052ff\" opacity=\".1\"/>\n          </svg>\n          <div class=\"cb-ui-rows\">\n            <div class=\"cb-ui-row\"><span>Line 04 · Luzon</span><span class=\"cb-up\">+2.4%</span></div>\n            <div class=\"cb-ui-row\"><span>Line 09 · Busan</span><span class=\"cb-down\">&minus;1.1%</span></div>\n          </div>\n        </article>\n        <article class=\"cb-ui-card cb-ui-float\">\n          <span class=\"cb-ui-label\">On-time dispatch</span>\n          <span class=\"cb-ui-figure\">98.1%</span>\n          <div class=\"cb-ui-meter\"><span style=\"width: 98%\"></span></div>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── SOFT ELEVATION BAND: asset rows ────────────────────────────────── -->\n    <section id=\"cb-explore\" class=\"cb-explore\" aria-labelledby=\"cbExploreH\">\n      <div class=\"cb-explore-head\">\n        <div>\n          <h2 id=\"cbExploreH\" class=\"cb-h2\">Every line, ranked by yield</h2>\n          <p class=\"cb-lead\">A governed view of the floor, refreshed every fifteen minutes.</p>\n        </div>\n        <label class=\"cb-search\">\n          <span class=\"cb-sr\">Search lines</span>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n          <input type=\"search\" placeholder=\"Search lines or regions\" autocomplete=\"off\">\n        </label>\n      </div>\n      <div class=\"cb-asset-list\" id=\"cbAssetList\"></div>\n    </section>\n\n    <!-- ── PLATFORM: 3-up feature cards on white ───────────────────────────── -->\n    <section id=\"cb-platform\" class=\"cb-platform\" aria-labelledby=\"cbPlatformH\">\n      <div class=\"cb-platform-head\">\n        <h2 id=\"cbPlatformH\" class=\"cb-h2\">Built like a ledger</h2>\n        <p class=\"cb-lead\">Layered, reconciled, and auditable — the way an operations number should be.</p>\n      </div>\n      <div class=\"cb-feature-grid\">\n        <article class=\"cb-feature\">\n          <span class=\"cb-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16M4 12h16M4 17h10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></span>\n          <h3>Governed metric model</h3>\n          <p>One definition per number. Versioned, certified, and read the same by every desk.</p>\n        </article>\n        <article class=\"cb-feature\">\n          <span class=\"cb-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3 4 6v6c0 5 3.4 8.6 8 9.6 4.6-1 8-4.6 8-9.6V6l-8-3Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m8.8 12 2.2 2.2 4.2-4.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>\n          <h3>Reconciliation first</h3>\n          <p>Every row carries its lineage. Disputes resolve to the source, not to a screenshot.</p>\n        </article>\n        <article class=\"cb-feature\">\n          <span class=\"cb-feature-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M12 7.5V12l3 2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></span>\n          <h3>Scheduled digests</h3>\n          <p>Each shift gets the reconciled board on their own clock, in their own inbox.</p>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── DARK FEATURE BAND ───────────────────────────────────────────────── -->\n    <section id=\"cb-institutions\" class=\"cb-dark\" aria-labelledby=\"cbDarkH\">\n      <div class=\"cb-dark-copy\">\n        <span class=\"cb-badge cb-badge-dark\">Regulated</span>\n        <h2 id=\"cbDarkH\" class=\"cb-h2 cb-h2-dark\">Controls the audit desk signs off on</h2>\n        <p class=\"cb-lead cb-lead-dark\">Row-level access, immutable lineage, and a full change history for every certified metric.</p>\n        <a class=\"cb-btn cb-btn-outline cb-btn-on-dark\" href=\"#cb-pricing\">Talk to sales</a>\n      </div>\n      <div class=\"cb-dark-panel\" aria-hidden=\"true\">\n        <div class=\"cb-audit-row\"><span class=\"cb-audit-k\">Access</span><span class=\"cb-audit-v\">Scoped by region &amp; role</span></div>\n        <div class=\"cb-audit-row\"><span class=\"cb-audit-k\">Lineage</span><span class=\"cb-audit-v\">Row-level, immutable</span></div>\n        <div class=\"cb-audit-row\"><span class=\"cb-audit-k\">Retention</span><span class=\"cb-audit-v\">7 years, exportable</span></div>\n        <div class=\"cb-audit-row\"><span class=\"cb-audit-k\">Attestation</span><span class=\"cb-audit-v\">SOC 2 Type II</span></div>\n      </div>\n    </section>\n\n    <!-- ── NUMBERS BAND ────────────────────────────────────────────────────── -->\n    <section id=\"cb-developers\" class=\"cb-numbers\" aria-label=\"Northwind at a glance\">\n      <div class=\"cb-number\"><span class=\"cb-number-fig\">316,258</span><span class=\"cb-number-lbl\">units reconciled daily</span></div>\n      <div class=\"cb-number\"><span class=\"cb-number-fig\">12</span><span class=\"cb-number-lbl\">regions on one ledger</span></div>\n      <div class=\"cb-number\"><span class=\"cb-number-fig\">$429M</span><span class=\"cb-number-lbl\">value recovered</span></div>\n      <div class=\"cb-number\"><span class=\"cb-number-fig\">99.98%</span><span class=\"cb-number-lbl\">model uptime</span></div>\n    </section>\n\n    <!-- ── PRICING ──────────────────────────────────────────────────────────── -->\n    <section id=\"cb-pricing\" class=\"cb-pricing\" aria-labelledby=\"cbPricingH\">\n      <div class=\"cb-pricing-head\">\n        <h2 id=\"cbPricingH\" class=\"cb-h2\">Simple, institutional pricing</h2>\n        <p class=\"cb-lead\">Start on a single line and expand per region. No card for the first 30 days.</p>\n      </div>\n      <div class=\"cb-tier-grid\">\n        <article class=\"cb-tier\">\n          <span class=\"cb-tier-name\">Line</span>\n          <span class=\"cb-tier-price\">$1,900<span>/mo</span></span>\n          <ul><li>1 region</li><li>Up to 10 seats</li><li>Weekly digests</li></ul>\n          <a class=\"cb-btn cb-btn-secondary\" href=\"#\">Choose Line</a>\n        </article>\n        <article class=\"cb-tier cb-tier-featured\">\n          <span class=\"cb-tier-name\">Operations</span>\n          <span class=\"cb-tier-price\">$4,900<span>/mo</span></span>\n          <ul><li>Up to 6 regions</li><li>40 seats included</li><li>Reconciliation engine</li></ul>\n          <a class=\"cb-btn cb-btn-primary\" href=\"#\">Choose Operations</a>\n        </article>\n        <article class=\"cb-tier\">\n          <span class=\"cb-tier-name\">Institution</span>\n          <span class=\"cb-tier-price\">Custom</span>\n          <ul><li>Unlimited regions</li><li>SSO &amp; audit</li><li>Dedicated model owner</li></ul>\n          <a class=\"cb-btn cb-btn-secondary\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────────── -->\n  <footer id=\"cb-company\" class=\"cb-foot\">\n    <div class=\"cb-foot-top\">\n      <a class=\"cb-wordmark cb-wordmark-foot\" href=\"#cb-top\">Northwind</a>\n      <form class=\"cb-foot-form\" id=\"cbFootForm\">\n        <label class=\"cb-sr\" for=\"cbFootEmail\">Email for product updates</label>\n        <input id=\"cbFootEmail\" type=\"email\" placeholder=\"you@company.com\" autocomplete=\"email\">\n        <button class=\"cb-btn cb-btn-primary cb-btn-sm\" type=\"submit\">Subscribe</button>\n      </form>\n    </div>\n    <div class=\"cb-foot-cols\">\n      <div class=\"cb-foot-col\"><h3>Product</h3><a href=\"#\">Ledger</a><a href=\"#\">Metric model</a><a href=\"#\">Digests</a><a href=\"#\">Integrations</a></div>\n      <div class=\"cb-foot-col\"><h3>Solutions</h3><a href=\"#\">Manufacturing</a><a href=\"#\">Logistics</a><a href=\"#\">Financial ops</a><a href=\"#\">Public sector</a></div>\n      <div class=\"cb-foot-col\"><h3>Developers</h3><a href=\"#\">Docs</a><a href=\"#\">API</a><a href=\"#\">Status</a><a href=\"#\">Changelog</a></div>\n      <div class=\"cb-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Newsroom</a><a href=\"#\">Legal</a></div>\n    </div>\n    <div class=\"cb-legal\">\n      <span>&copy; 2026 Northwind Analytics — a fictional product. Sample data, showcase only.</span>\n      <span class=\"cb-legal-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in Coinbase's design language, for showcase.html ════════════\n   Institutional-grade marketing surfaces: pure-white canvas, a single brand\n   voltage (Coinbase Blue #0052ff) used scarcely, display type at weight 400 with\n   negative tracking, pill CTAs (100px), 24px cards, 96px section rhythm, and a\n   full-bleed near-black hero carrying layered product-ui mockup cards. Numbers\n   render in a mono face. Depth is card-on-card, never decorative shadows. */\n\n.own-coinbase {\n  --primary: #0052ff;\n  --primary-active: #003ecc;\n  --primary-disabled: #a8b8cc;\n  --ink: #0a0b0d;\n  --body: #5b616e;\n  --muted: #7c828a;\n  --muted-soft: #a8acb3;\n  --hairline: #dee1e6;\n  --hairline-soft: #eef0f3;\n  --canvas: #ffffff;\n  --surface-soft: #f7f7f7;\n  --surface-strong: #eef0f3;\n  --surface-dark: #0a0b0d;\n  --surface-dark-elevated: #16181c;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --on-dark-soft: #a8acb3;\n  --semantic-up: #05b169;\n  --semantic-down: #cf202f;\n  --accent-yellow: #f4b000;\n\n  --font-display: 'Coinbase Display', 'Inter', -apple-system, system-ui, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n  --font-body: 'Coinbase Sans', 'Inter', -apple-system, system-ui, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n  --font-mono: 'Coinbase Mono', 'JetBrains Mono', 'Geist Mono', ui-monospace, monospace;\n\n  --r-xs: 4px;\n  --r-sm: 8px;\n  --r-md: 12px;\n  --r-lg: 16px;\n  --r-xl: 24px;\n  --r-pill: 100px;\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-body);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-coinbase *, .own-coinbase *::before, .own-coinbase *::after { box-sizing: border-box; }\n.own-coinbase a { color: inherit; text-decoration: none; }\n.own-coinbase button { font: inherit; cursor: pointer; }\n.own-coinbase :focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; border-radius: 6px; }\n.own-coinbase .cb-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── nav ───────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-nav { position: sticky; top: 68px; z-index: 40; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 var(--gut); background: rgba(255, 255, 255, .9); border-bottom: 1px solid var(--hairline); backdrop-filter: saturate(180%) blur(12px); -webkit-backdrop-filter: saturate(180%) blur(12px); }\n.own-coinbase .cb-wordmark { font-family: var(--font-display); font-size: 22px; font-weight: 400; letter-spacing: -0.5px; color: var(--primary); }\n.own-coinbase .cb-menu { display: flex; gap: 26px; margin: 0 auto; font-size: 14px; font-weight: 500; color: var(--ink); }\n.own-coinbase .cb-menu a { padding: 4px 0; }\n.own-coinbase .cb-menu a:hover { color: var(--primary); }\n.own-coinbase .cb-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-coinbase .cb-nav-link { font-size: 14px; font-weight: 500; }\n.own-coinbase .cb-nav-link:hover { color: var(--primary); }\n.own-coinbase .cb-ico { display: grid; place-items: center; width: 36px; height: 36px; border: 0; border-radius: 50%; background: transparent; color: var(--ink); }\n.own-coinbase .cb-ico:hover { background: var(--surface-strong); }\n.own-coinbase .cb-ico svg { width: 18px; height: 18px; }\n.own-coinbase .cb-burger { display: none; flex-direction: column; gap: 4px; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--hairline); border-radius: var(--r-sm); background: var(--canvas); }\n.own-coinbase .cb-burger span { display: block; width: 18px; height: 2px; background: var(--ink); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 44px; padding: 0 20px; border: 0; border-radius: var(--r-pill); font-family: var(--font-body); font-size: 16px; font-weight: 600; line-height: 1.15; transition: background-color .18s, border-color .18s; }\n.own-coinbase .cb-btn-sm { height: 40px; padding: 0 18px; font-size: 14px; }\n.own-coinbase .cb-btn-lg { height: 56px; padding: 0 32px; }\n.own-coinbase .cb-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-coinbase .cb-btn-primary:hover { background: var(--primary-active); }\n.own-coinbase .cb-btn-secondary { background: var(--surface-strong); color: var(--ink); }\n.own-coinbase .cb-btn-secondary:hover { background: #e2e6ea; }\n.own-coinbase .cb-btn-outline { background: transparent; color: var(--on-dark); border: 1px solid rgba(255, 255, 255, .4); }\n.own-coinbase .cb-btn-outline:hover { border-color: #fff; }\n.own-coinbase .cb-btn-on-dark { border-color: rgba(255, 255, 255, .4); }\n\n/* ── badges ────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-badge { display: inline-block; padding: 4px 12px; border-radius: var(--r-pill); background: var(--surface-strong); color: var(--ink); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }\n.own-coinbase .cb-badge-dark { background: rgba(255, 255, 255, .12); color: var(--on-dark); }\n\n/* ── hero ──────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-hero { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 4cqi, 56px); align-items: center; padding: var(--section) var(--gut); background: var(--surface-dark); color: var(--on-dark); }\n.own-coinbase .cb-hero-title { font-family: var(--font-display); font-size: clamp(40px, 6.4cqi, 80px); font-weight: 400; line-height: 1; letter-spacing: -0.025em; margin-top: 18px; }\n.own-coinbase .cb-hero-sub { margin-top: 20px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--on-dark-soft); }\n.own-coinbase .cb-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }\n\n/* layered product-ui mockup cards */\n.own-coinbase .cb-hero-stack { position: relative; min-height: 340px; }\n.own-coinbase .cb-ui-card { background: var(--surface-dark-elevated); border: 1px solid rgba(255, 255, 255, .08); border-radius: var(--r-xl); padding: 28px; }\n.own-coinbase .cb-ui-main { position: relative; z-index: 1; }\n.own-coinbase .cb-ui-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }\n.own-coinbase .cb-ui-title { font-size: 16px; font-weight: 600; color: var(--on-dark); }\n.own-coinbase .cb-ui-live { font-size: 12px; font-weight: 600; color: var(--semantic-up); }\n.own-coinbase .cb-ui-balance { display: grid; gap: 4px; }\n.own-coinbase .cb-ui-label { font-size: 13px; color: var(--on-dark-soft); }\n.own-coinbase .cb-ui-amount { font-family: var(--font-mono); font-size: clamp(30px, 3.4cqi, 44px); font-weight: 500; line-height: 1.1; letter-spacing: -0.5px; }\n.own-coinbase .cb-ui-chart { width: 100%; height: 84px; margin: 18px 0 10px; }\n.own-coinbase .cb-ui-rows { display: grid; gap: 10px; }\n.own-coinbase .cb-ui-row { display: flex; align-items: center; justify-content: space-between; font-size: 14px; color: var(--on-dark-soft); }\n.own-coinbase .cb-up { font-family: var(--font-mono); color: var(--semantic-up); font-weight: 500; }\n.own-coinbase .cb-down { font-family: var(--font-mono); color: var(--semantic-down); font-weight: 500; }\n.own-coinbase .cb-ui-float { position: absolute; right: 0; bottom: -28px; width: min(240px, 70%); z-index: 2; box-shadow: 0 24px 60px rgba(0, 0, 0, .45); }\n.own-coinbase .cb-ui-figure { display: block; margin-top: 4px; font-family: var(--font-mono); font-size: 34px; font-weight: 500; letter-spacing: -0.5px; }\n.own-coinbase .cb-ui-meter { margin-top: 12px; height: 8px; border-radius: var(--r-pill); background: rgba(255, 255, 255, .12); overflow: hidden; }\n.own-coinbase .cb-ui-meter span { display: block; height: 100%; border-radius: var(--r-pill); background: var(--primary); }\n\n/* ── explore / asset rows ──────────────────────────────────────────────────── */\n.own-coinbase .cb-explore { padding: var(--section) var(--gut); background: var(--surface-soft); }\n.own-coinbase .cb-explore-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin-bottom: 28px; }\n.own-coinbase .cb-h2 { font-family: var(--font-display); font-size: clamp(32px, 4.4cqi, 52px); font-weight: 400; line-height: 1; letter-spacing: -0.025em; }\n.own-coinbase .cb-lead { margin-top: 12px; max-width: 52ch; font-size: 16px; line-height: 1.5; color: var(--body); }\n.own-coinbase .cb-search { display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 20px; border-radius: var(--r-pill); background: var(--surface-strong); min-width: 280px; }\n.own-coinbase .cb-search svg { width: 18px; height: 18px; color: var(--muted); flex: none; }\n.own-coinbase .cb-search input { width: 100%; border: 0; background: none; color: var(--ink); font: inherit; font-size: 15px; }\n.own-coinbase .cb-search input:focus { outline: none; }\n.own-coinbase .cb-asset-list { display: grid; }\n.own-coinbase .cb-asset { display: grid; grid-template-columns: 44px 1.6fr 1fr 1fr; align-items: center; gap: 16px; padding: 18px 8px; border-top: 1px solid var(--hairline); }\n.own-coinbase .cb-asset:last-child { border-bottom: 1px solid var(--hairline); }\n.own-coinbase .cb-asset-ico { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9999px; background: var(--surface-strong); font-family: var(--font-mono); font-size: 12px; font-weight: 600; color: var(--ink); }\n.own-coinbase .cb-asset-name { display: grid; gap: 2px; }\n.own-coinbase .cb-asset-name b { font-size: 16px; font-weight: 600; }\n.own-coinbase .cb-asset-name span { font-size: 13px; color: var(--muted); }\n.own-coinbase .cb-asset-price { font-family: var(--font-mono); font-size: 16px; font-weight: 500; text-align: right; }\n.own-coinbase .cb-asset-chg { font-family: var(--font-mono); font-size: 16px; font-weight: 500; text-align: right; }\n.own-coinbase .cb-chg-up { color: var(--semantic-up); }\n.own-coinbase .cb-chg-down { color: var(--semantic-down); }\n\n/* ── platform feature cards ─────────────────────────────────────────────────── */\n.own-coinbase .cb-platform { padding: var(--section) var(--gut); }\n.own-coinbase .cb-platform-head { text-align: center; max-width: 720px; margin: 0 auto clamp(32px, 5cqi, 56px); }\n.own-coinbase .cb-feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-coinbase .cb-feature { padding: 32px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--canvas); }\n.own-coinbase .cb-feature-ico { display: grid; place-items: center; width: 44px; height: 44px; border-radius: var(--r-md); background: var(--surface-strong); color: var(--primary); margin-bottom: 20px; }\n.own-coinbase .cb-feature-ico svg { width: 22px; height: 22px; }\n.own-coinbase .cb-feature h3 { font-size: 18px; font-weight: 600; line-height: 1.33; }\n.own-coinbase .cb-feature p { margin-top: 10px; font-size: 16px; line-height: 1.5; color: var(--body); }\n\n/* ── dark feature band ──────────────────────────────────────────────────────── */\n.own-coinbase .cb-dark { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 4cqi, 56px); align-items: center; padding: var(--section) var(--gut); background: var(--surface-dark); color: var(--on-dark); }\n.own-coinbase .cb-h2-dark { color: var(--on-dark); }\n.own-coinbase .cb-lead-dark { color: var(--on-dark-soft); }\n.own-coinbase .cb-dark-copy .cb-btn { margin-top: 28px; }\n.own-coinbase .cb-dark-panel { display: grid; gap: 1px; border: 1px solid rgba(255, 255, 255, .1); border-radius: var(--r-xl); overflow: hidden; }\n.own-coinbase .cb-audit-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 20px 24px; background: var(--surface-dark-elevated); }\n.own-coinbase .cb-audit-k { font-size: 13px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--on-dark-soft); }\n.own-coinbase .cb-audit-v { font-size: 15px; color: var(--on-dark); }\n\n/* ── numbers ────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-numbers { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding: clamp(40px, 6cqi, 72px) var(--gut); background: var(--canvas); border-top: 1px solid var(--hairline-soft); border-bottom: 1px solid var(--hairline-soft); }\n.own-coinbase .cb-number { display: grid; gap: 6px; }\n.own-coinbase .cb-number-fig { font-family: var(--font-mono); font-size: clamp(28px, 3.6cqi, 44px); font-weight: 500; line-height: 1; letter-spacing: -0.5px; color: var(--primary); }\n.own-coinbase .cb-number-lbl { font-size: 14px; color: var(--body); }\n\n/* ── pricing ────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-pricing { padding: var(--section) var(--gut); background: var(--surface-soft); }\n.own-coinbase .cb-pricing-head { text-align: center; max-width: 720px; margin: 0 auto clamp(32px, 5cqi, 56px); }\n.own-coinbase .cb-tier-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: stretch; }\n.own-coinbase .cb-tier { display: grid; gap: 12px; align-content: start; padding: 32px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--canvas); }\n.own-coinbase .cb-tier-name { font-size: 14px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }\n.own-coinbase .cb-tier-price { font-family: var(--font-display); font-size: clamp(30px, 3.4cqi, 44px); font-weight: 400; letter-spacing: -1px; }\n.own-coinbase .cb-tier-price span { font-family: var(--font-body); font-size: 15px; color: var(--muted); letter-spacing: 0; }\n.own-coinbase .cb-tier ul { list-style: none; display: grid; gap: 10px; margin: 8px 0 12px; padding-top: 18px; border-top: 1px solid var(--hairline); font-size: 15px; color: var(--body); }\n.own-coinbase .cb-tier .cb-btn { width: 100%; }\n.own-coinbase .cb-tier-featured { background: var(--surface-dark); border-color: var(--surface-dark); color: var(--on-dark); }\n.own-coinbase .cb-tier-featured .cb-tier-name { color: var(--on-dark-soft); }\n.own-coinbase .cb-tier-featured ul { border-top-color: rgba(255, 255, 255, .14); color: var(--on-dark-soft); }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-coinbase .cb-foot { padding: clamp(48px, 6cqi, 80px) var(--gut) 32px; background: var(--canvas); }\n.own-coinbase .cb-foot-top { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; padding-bottom: 40px; border-bottom: 1px solid var(--hairline); }\n.own-coinbase .cb-wordmark-foot { font-size: 26px; }\n.own-coinbase .cb-foot-form { display: flex; gap: 10px; flex-wrap: wrap; }\n.own-coinbase .cb-foot-form input { width: min(280px, 60cqi); height: 40px; padding: 0 16px; border: 1px solid var(--hairline); border-radius: var(--r-pill); font: inherit; font-size: 15px; background: var(--canvas); color: var(--ink); }\n.own-coinbase .cb-foot-form input:focus { outline: none; border-color: var(--primary); }\n.own-coinbase .cb-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding: 40px 0; }\n.own-coinbase .cb-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-coinbase .cb-foot-col h3 { font-size: 14px; font-weight: 600; margin-bottom: 4px; }\n.own-coinbase .cb-foot-col a { font-size: 14px; color: var(--body); }\n.own-coinbase .cb-foot-col a:hover { color: var(--primary); }\n.own-coinbase .cb-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--hairline); font-size: 13px; color: var(--muted); }\n.own-coinbase .cb-legal-links { display: flex; gap: 18px; }\n.own-coinbase .cb-legal-links a { color: var(--muted); }\n.own-coinbase .cb-legal-links a:hover { color: var(--ink); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-coinbase .cb-menu { display: none; }\n  .own-coinbase .cb-burger { display: flex; }\n  .own-coinbase .cb-hero { grid-template-columns: 1fr; }\n  .own-coinbase .cb-hero-stack { min-height: 0; }\n  .own-coinbase .cb-ui-float { position: static; width: 100%; margin-top: 20px; box-shadow: none; }\n  .own-coinbase .cb-feature-grid { grid-template-columns: 1fr; }\n  .own-coinbase .cb-dark { grid-template-columns: 1fr; }\n  .own-coinbase .cb-tier-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-coinbase .cb-nav { top: 66px; height: 58px; gap: 10px; }\n  .own-coinbase .cb-numbers { grid-template-columns: repeat(2, 1fr); }\n  .own-coinbase .cb-asset { grid-template-columns: 40px 1fr; row-gap: 6px; }\n  .own-coinbase .cb-asset-price, .own-coinbase .cb-asset-chg { text-align: left; }\n  .own-coinbase .cb-asset-price { grid-column: 2; }\n  .own-coinbase .cb-asset-chg { grid-column: 2; }\n  .own-coinbase .cb-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-coinbase .cb-hero-cta { flex-direction: column; align-items: stretch; }\n  .own-coinbase .cb-numbers { grid-template-columns: 1fr; }\n  .own-coinbase .cb-foot-cols { grid-template-columns: 1fr; }\n  .own-coinbase .cb-explore-head { align-items: stretch; }\n  .own-coinbase .cb-search { min-width: 0; width: 100%; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-coinbase *, .own-coinbase *::before, .own-coinbase *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in Coinbase's design language, for showcase.html ════════════
   Registers window.OWN_LAYOUTS['coinbase'].init(root). Renders the asset-row
   list from sample data, wires the footer subscription form, and returns a
   cleanup that detaches every listener. Hover/transition only — no idle motion. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var LINES = [
    { name: 'Line 04', region: 'Luzon', price: '98.4%', chg: '+2.4%', up: true },
    { name: 'Line 09', region: 'Busan', price: '94.6%', chg: '\u22121.1%', up: false },
    { name: 'Line 02', region: 'Luzon', price: '99.1%', chg: '+0.6%', up: true },
    { name: 'Line 11', region: 'Jurong', price: '96.2%', chg: '+1.3%', up: true },
    { name: 'Line 07', region: 'Busan', price: '92.8%', chg: '\u22122.7%', up: false }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function initials(s) { return String(s).replace(/[^A-Za-z0-9]/g, '').slice(0, 2).toUpperCase(); }

  OWN['coinbase'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(s) { return root.querySelector(s); }

      var list = $('#cbAssetList');
      if (list) {
        list.innerHTML = LINES.map(function (l) {
          return '<div class="cb-asset">'
            + '<span class="cb-asset-ico" aria-hidden="true">' + esc(initials(l.name)) + '</span>'
            + '<span class="cb-asset-name"><b>' + esc(l.name) + '</b><span>' + esc(l.region) + '</span></span>'
            + '<span class="cb-asset-price">' + esc(l.price) + '</span>'
            + '<span class="cb-asset-chg ' + (l.up ? 'cb-chg-up' : 'cb-chg-down') + '">' + esc(l.chg) + '</span>'
            + '</div>';
        }).join('');
      }

      var form = $('#cbFootForm');
      on(form, 'submit', function (e) {
        e.preventDefault();
        var input = $('#cbFootEmail');
        if (input) { input.value = ''; input.placeholder = 'Thanks — sample data only'; }
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
